def is_palindrome(n):
    return str(n) == str(n)[::-1]

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    # Use a deque to store the palindromes in a more efficient way
    palindrome_queue = deque()
    for i in range(1, n+1):
        if is_palindrome(i):
            palindrome_queue.append(i)

    # Check if the first element is even or odd, then remove it from the queue
    if palindrome_queue[0] % 2 == 0:
        even_count += 1
        palindrome_queue.popleft()
    else:
        odd_count += 1
        palindrome_queue.popleft()

    # Check the rest of the palindromes in the queue
    while palindrome_queue:
        if palindrome_queue[0] % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
        palindrome_queue.popleft()

    return even_count, odd_count
